import json
from statistics import mean, median

rows = json.load(open("eval/_sss_partial.json"))
rows.sort(key=lambda r: int(r["paper_id"]))
for r in rows:
    r["pct_reduction"] = 100.0 * (1 - r["n_selected"] / r["n_original"])

lines = []
lines.append("# Sentence selection — real statistics across the 21-paper corpus\n")
lines.append(
    "Generated by running `pipeline/summarization.py`'s production ontology-gate scoring "
    "(same defaults as `pipeline/domain_pipeline.py`: `num_sentences=20`, `min_total_score=2.5`) "
    "against all 21 real papers in `llm/finetuning/papers/*.tei.xml` (via `pipeline.parser.tei_to_text`, "
    "no GROBID service or network access needed). Executed directly, in batches, due to the ontology-gate "
    "scoring cost per paper (~1-5s/paper); see `sentence_selection_stats.py` in this directory for the "
    "reusable, single-command version of this same logic.\n"
)
lines.append("## Per-paper\n")
lines.append("| Paper | Original sentences | After ontology filter | Final selected | % reduction |")
lines.append("|---|---|---|---|---|")
for r in rows:
    lines.append(f"| {r['paper_id']} | {r['n_original']} | {r['n_ontology_filtered']} | "
                 f"{r['n_selected']} | {r['pct_reduction']:.1f}% |")

orig = [r["n_original"] for r in rows]
filt = [r["n_ontology_filtered"] for r in rows]
sel = [r["n_selected"] for r in rows]
pct = [r["pct_reduction"] for r in rows]

lines.append("\n## Aggregate (n=21 papers)\n")
lines.append("| | mean | median | min | max |")
lines.append("|---|---|---|---|---|")
lines.append(f"| Original sentences | {mean(orig):.1f} | {median(orig):.1f} | {min(orig)} | {max(orig)} |")
lines.append(f"| After ontology filter | {mean(filt):.1f} | {median(filt):.1f} | {min(filt)} | {max(filt)} |")
lines.append(f"| Final selected | {mean(sel):.1f} | {median(sel):.1f} | {min(sel)} | {max(sel)} |")
lines.append(f"| % reduction (original -> final) | {mean(pct):.1f}% | {median(pct):.1f}% | {min(pct):.1f}% | {max(pct):.1f}% |")

n_capped = sum(1 for r in rows if r["n_ontology_filtered"] > 20)
below5 = [r["paper_id"] for r in rows if r["n_ontology_filtered"] < 5]
lines.append(
    f"\n{n_capped}/21 papers had more than 20 ontology-filtered sentences (clustering performed a "
    f"further reduction); {21 - n_capped}/21 had 20 or fewer (all filtered sentences kept, no "
    f"clustering reduction applied). {len(below5)}/21 papers produced fewer than 5 ontology-filtered "
    f"sentences (papers {', '.join(below5)} — below the `min_summary_sentences=5` floor the domain "
    f"gate checks; these would be flagged `insufficient_moulting_content` by "
    f"`analyze_paper_and_query_domain` despite containing real, annotated moulting content in the "
    f"MoultDB ground truth — a genuine limitation of the fixed-threshold gate worth noting explicitly "
    f"in the paper rather than glossed over.)\n"
)

with open("eval/sentence_selection_stats.md", "w", encoding="utf-8") as f:
    f.write("\n".join(lines) + "\n")

print("\n".join(lines))
